import { beforeEach, describe, expect, it } from 'vitest';
import { useBookmarks } from './bookmarks';

describe('Bookmarks Store', () => {
  beforeEach(() => {
    useBookmarks.getState().ids = [];
    localStorage.clear();
  });

  it('starts empty', () => {
    expect(useBookmarks.getState().ids).toEqual([]);
  });

  it('adds item', () => {
    useBookmarks.getState().add('id-1');
    expect(useBookmarks.getState().ids).toEqual(['id-1']);
    expect(useBookmarks.getState().has('id-1')).toBe(true);
  });

  it('does not add duplicates', () => {
    useBookmarks.getState().add('id-1');
    useBookmarks.getState().add('id-1');
    expect(useBookmarks.getState().ids).toEqual(['id-1']);
  });

  it('removes item', () => {
    useBookmarks.getState().add('id-1');
    useBookmarks.getState().remove('id-1');
    expect(useBookmarks.getState().ids).toEqual([]);
    expect(useBookmarks.getState().has('id-1')).toBe(false);
  });

  it('removes non-existent item safely', () => {
    useBookmarks.getState().add('id-1');
    useBookmarks.getState().remove('id-2');
    expect(useBookmarks.getState().ids).toEqual(['id-1']);
  });

  it('persists to storage', () => {
    useBookmarks.getState().add('persistent');
    // Проверяем, что метод был вызван (так как мы замокали его глобально через vi.fn)
    expect(localStorage.setItem).toHaveBeenCalledWith(
      'bookmarks-storage',
      expect.stringContaining('persistent'),
    );
  });
});

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface BookmarksState {
  ids: string[];
  has: (id: string) => boolean;
  add: (id: string) => void;
  remove: (id: string) => void;
}

export const useBookmarks = create<BookmarksState>()(
  persist(
    (set, get) => ({
      ids: [],
      has: (id) => get().ids.includes(id),
      // 🛡️ L4 Fix: Проверяем наличие перед добавлением
      add: (id) => set((state) => (state.ids.includes(id) ? state : { ids: [...state.ids, id] })),
      remove: (id) => set((state) => ({ ids: state.ids.filter((i) => i !== id) })),
    }),
    { name: 'bookmarks-storage' },
  ),
);

import { renderHook } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import * as telegramModule from '../infrastructure/telegram';
import { useTelegramInit, useTelegramTheme, useTelegramUser } from './useTelegram';

// Мокаем telegram.ts
vi.mock('../infrastructure/telegram', () => ({
  initTelegram: vi.fn(),
  getTelegramUser: vi.fn(),
  getTelegramTheme: vi.fn(),
}));

describe('useTelegram hooks', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('useTelegramInit', () => {
    it('инициализирует SDK и возвращает статус', () => {
      (telegramModule.initTelegram as ReturnType<typeof vi.fn>).mockReturnValue({
        isAvailable: true,
        initData: 'test',
      });

      const { result } = renderHook(() => useTelegramInit());
      expect(result.current.isInitialized).toBe(true);
      expect(result.current.isInTelegram).toBe(true);
    });

    it('обрабатывает отсутствие Telegram SDK', () => {
      (telegramModule.initTelegram as ReturnType<typeof vi.fn>).mockReturnValue(null);

      const { result } = renderHook(() => useTelegramInit());
      expect(result.current.isInitialized).toBe(true);
      expect(result.current.isInTelegram).toBe(false);
    });
  });

  describe('useTelegramUser', () => {
    it('возвращает данные пользователя', () => {
      (telegramModule.getTelegramUser as ReturnType<typeof vi.fn>).mockReturnValue({
        id: 123,
        firstName: 'Test',
      });

      const { result } = renderHook(() => useTelegramUser());
      expect(result.current).toMatchObject({
        id: 123,
        firstName: 'Test',
      });
    });

    it('возвращает null если нет пользователя', () => {
