import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { storage } from './storage';

// Создаем "мок" (фальшивый) localStorage, чтобы контролировать его
const createMockLocalStorage = (available = true) => {
  let store: Record<string, string> = {};

  if (!available) {
    // Если localStorage недоступен (инкогнито в Safari и т.д.)
    const error = new Error('LocalStorage is not available');
    return {
      getItem: () => {
        throw error;
      },
      setItem: () => {
        throw error;
      },
      removeItem: () => {
        throw error;
      },
      clear: () => {
        store = {};
      },
    };
  }

  // Обычный рабочий localStorage
  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      // Имитируем ошибку "Quota Exceeded" (переполнение)
      if (key === 'FAIL_SET') {
        throw new Error('Quota Exceeded');
      }
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    },
  };
};

// Перехватываем "window.localStorage" и подменяем его нашим моком
const mockStorage = createMockLocalStorage();

vi.stubGlobal('localStorage', mockStorage);

describe('Infrastructure: storage', () => {
  // Сбрасываем хранилище перед каждым тестом
  beforeEach(() => {
    mockStorage.clear();
  });

  // Восстанавливаем настоящий localStorage после всех тестов
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('should set and get a value', () => {
    const data = { id: 1, name: 'test' };
    storage.set('myKey', data);

    const retrieved = storage.get('myKey');
    expect(retrieved).toEqual(data);
  });

  it('should return null if key does not exist', () => {
    const retrieved = storage.get('badKey');
    expect(retrieved).toBeNull();
  });

  it('should delete a value', () => {
    storage.set('myKey', { id: 1 });
    storage.del('myKey');

    const retrieved = storage.get('myKey');
    expect(retrieved).toBeNull();
  });

  it('should return null if JSON.parse fails', () => {
    mockStorage.setItem('badJSON', '{invalid_json:');

    const retrieved = storage.get('badJSON');
    expect(retrieved).toBeNull();
  });

  it('should return null if localStorage.getItem fails', () => {
    vi.stubGlobal('localStorage', createMockLocalStorage(false));

    const retrieved = storage.get('anyKey');
    expect(retrieved).toBeNull();

    vi.stubGlobal('localStorage', mockStorage);
  });

  it('should not throw if localStorage.setItem fails (Quota)', () => {
    expect(() => {
      storage.set('FAIL_SET', { id: 1 });
    }).not.toThrow();
  });

  it('should not throw if localStorage.removeItem fails', () => {
    vi.stubGlobal('localStorage', createMockLocalStorage(false));

    expect(() => {
      storage.del('anyKey');
    }).not.toThrow();

    vi.stubGlobal('localStorage', mockStorage);
  });
});

export const storage = {
  get<T>(key: string): T | null {
    try {
      const raw = localStorage.getItem(key);
      return raw ? (JSON.parse(raw) as T) : null;
    } catch {
      return null; // parse/JSON/localStorage error → тихий фолбэк
    }
  },
  set(key: string, value: unknown) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      void 0; // quota/offline — игнорируем
    }
  },
  del(key: string) {
    try {
      localStorage.removeItem(key);
    } catch {
      void 0; // приватный режим/ограничения — игнорируем
    }
  },
};

/**
 * Telegram Mini App SDK Integration
 * Современная интеграция с Telegram WebApp API v3.x
 */

import { init, retrieveLaunchParams } from '@telegram-apps/sdk-react';

export interface TelegramUser {
  id: number;
  firstName: string;
  lastName?: string;
  username?: string;
  languageCode?: string;
  isPremium?: boolean;
}

/**
 * Инициализация Telegram SDK
 * Вызывать один раз при старте приложения
 */
export function initTelegram() {
  if (typeof window === 'undefined') {
    console.warn('[Telegram] Not in browser environment');
    return null;
  }

  try {
    // Получаем параметры запуска
    const launchParams = retrieveLaunchParams();

    // Инициализируем SDK компоненты
    init();

    console.log('[Telegram] SDK initialized successfully');
    return launchParams;
  } catch (error) {
    console.warn('[Telegram] Not running in Telegram environment', error);
    return null;
  }
}

/**
 * Получить данные пользователя Telegram
 */
export function getTelegramUser(): TelegramUser | null {
  try {
    const launchParams = retrieveLaunchParams();
    const user = launchParams?.initData?.user;

    if (!user) {
      return null;
    }

    return {
      id: user.id,
      firstName: user.firstName,
      lastName: user.lastName,
      username: user.username,
      languageCode: user.languageCode,
      isPremium: user.isPremium,
    };
  } catch {
    return null;
  }
}

/**
 * Получить текущую тему Telegram
 */
export function getTelegramTheme() {
  try {
    const launchParams = retrieveLaunchParams();
    const theme = launchParams?.themeParams;

    if (!theme) {
      return null;
    }

    return {
      colorScheme: launchParams.colorScheme || 'dark',
      bgColor: theme.bgColor || theme.backgroundColor,
      textColor: theme.textColor,
      hintColor: theme.hintColor,
      linkColor: theme.linkColor,
      buttonColor: theme.buttonColor,
      buttonTextColor: theme.buttonTextColor,
    };
  } catch {
    return null;
  }
}

