function setupSpeechSynthesis() {
  const cancel = vi.fn();
  const speak = vi.fn();

  class FakeUtterance {
    text: string;

    constructor(text: string) {
      this.text = text;
    }
  }

  (window as unknown as { speechSynthesis?: unknown }).speechSynthesis = {
    cancel,
    speak,
  };
  (window as unknown as { SpeechSynthesisUtterance?: unknown }).SpeechSynthesisUtterance =
    FakeUtterance as unknown;

  return { cancel, speak, FakeUtterance };
}

function clearSpeechSynthesis() {
  delete (window as { speechSynthesis?: unknown }).speechSynthesis;
  delete (window as { SpeechSynthesisUtterance?: unknown }).SpeechSynthesisUtterance;
}

describe('application TTS integration (mutation)', () => {
  beforeEach(() => {
    vi.resetModules();
    clearSpeechSynthesis();
  });

  afterEach(() => {
    clearSpeechSynthesis();
    vi.restoreAllMocks();
  });

  it('returns false and stays safe when speech synthesis is unavailable', async () => {
    const { isSupported, stop, speakFromHtml } = await import('./tts');

    expect(isSupported()).toBe(false);
    await expect(speakFromHtml('Title', '<p>Body</p>')).resolves.toBeUndefined();
    expect(() => stop()).not.toThrow();
  });

  it('uses window.speechSynthesis and builds correct utterance text', async () => {
    const { cancel, speak, FakeUtterance } = setupSpeechSynthesis();
    const tts = await import('./tts');

    expect(tts.isSupported()).toBe(true);

    await tts.speakFromHtml('Ritual title', '<p>Hello <strong>world</strong></p>');

    expect(cancel).toHaveBeenCalledTimes(1);
    expect(speak).toHaveBeenCalledTimes(1);

    const utterArg = speak.mock.calls[0][0] as InstanceType<typeof FakeUtterance>;
    expect(utterArg).toBeInstanceOf(FakeUtterance);
    expect(utterArg.text).toBe('Ritual title. Hello world');
  });

  it('does not call speak when cleaned text is empty', async () => {
    const { speak } = setupSpeechSynthesis();
    const tts = await import('./tts');

    await tts.speakFromHtml('', '   <div>   </div>  ');

    expect(speak).not.toHaveBeenCalled();
  });

  it('swallows cancel/speak errors and logs them', async () => {
    const cancel = vi.fn(() => {
      throw new Error('cancel-fail');
    });
    const speak = vi.fn(() => {
      throw new Error('speak-fail');
    });

    class FakeUtterance {
      text: string;

      constructor(text: string) {
        this.text = text;
      }
    }

    (window as unknown as { speechSynthesis?: unknown }).speechSynthesis = {
      cancel,
      speak,
    };
    (window as unknown as { SpeechSynthesisUtterance?: unknown }).SpeechSynthesisUtterance =
      FakeUtterance as unknown;

    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

    const tts = await import('./tts');

    // Проверяем ошибку при cancel
    await tts.stop();
    // UEC FIX: Проверяем точный текст ошибки, чтобы убить мутанта (замена текста на пустую строку)
    expect(errorSpy).toHaveBeenCalledWith('TTS error during cancel:', expect.any(Error));
    errorSpy.mockClear();

    // Проверяем ошибку при speak
    await tts.speakFromHtml('Title', '<p>Body</p>');
    expect(errorSpy).toHaveBeenCalledWith('TTS error during speak:', expect.any(Error));

    errorSpy.mockRestore();
  });
});

// src/application/tts.ts

// Безопасная ссылка на SpeechSynthesis (в браузере)
const synth: SpeechSynthesis | null =
  typeof window !== 'undefined' &&
  // biome-ignore lint/security/noSecrets: 'speechSynthesis' — имя Web API, а не секрет
  'speechSynthesis' in window
    ? window.speechSynthesis
    : null;

/** Проверка поддержки Web Speech API (TTS) */
export function isSupported(): boolean {
  return !!synth;
}

/** Остановить озвучивание (если поддерживается) */
export function stop(): void {
  if (!synth) {
    return;
  }
  try {
    synth.cancel();
  } catch (error) {
    console.error('TTS error during cancel:', error);
  }
}

/** Озвучить: берём title + «голый» текст из HTML (без тегов) */
export async function speakFromHtml(title: string, html: string): Promise<void> {
  if (!synth) {
    return;
  }

  // На всякий случай гасим предыдущее
  stop();

  // Удаляем все теги
  const body = html.replace(/<[^>]*>/g, '').trim();
  const text = (title ? `${title}. ` : '') + body;

  if (!text) {
    return;
  }

  const utter = new SpeechSynthesisUtterance(text);
  // Настройка голоса (если требуется)

  try {
    synth.speak(utter);
  } catch (error) {
    console.error('TTS error during speak:', error);
  }
}

