import { describe, it, expect } from 'vitest';
import {
  GRID_SIZE,
  TOTAL_DISTRICTS,
  CENTRAL_DISTRICTS,
  CORNER_DISTRICTS,
  getDistrictIndex,
  getCoordinates,
  areDistrictsAdjacent,
  getAdjacentDistricts,
} from './gameConstants';

describe('City Mystery helpers: grid geometry', () => {
  it('GRID_SIZE and TOTAL_DISTRICTS should be consistent', () => {
    expect(GRID_SIZE).toBe(4);
    expect(TOTAL_DISTRICTS).toBe(GRID_SIZE * GRID_SIZE);
  });

  it('getDistrictIndex and getCoordinates should be inverse operations', () => {
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        const index = getDistrictIndex(x, y);
        const { x: rx, y: ry } = getCoordinates(index);

        expect(index).toBeGreaterThanOrEqual(0);
        expect(index).toBeLessThan(TOTAL_DISTRICTS);
        expect(rx).toBe(x);
        expect(ry).toBe(y);
      }
    }
  });

  it('areDistrictsAdjacent should detect neighbors correctly (4-neighborhood)', () => {
    // проверяем центр поля (1,1) -> индекс 5
    const centerIndex = getDistrictIndex(1, 1);
    const up = getDistrictIndex(1, 0);
    const down = getDistrictIndex(1, 2);
    const left = getDistrictIndex(0, 1);
    const right = getDistrictIndex(2, 1);

    expect(areDistrictsAdjacent(centerIndex, up)).toBe(true);
    expect(areDistrictsAdjacent(centerIndex, down)).toBe(true);
    expect(areDistrictsAdjacent(centerIndex, left)).toBe(true);
    expect(areDistrictsAdjacent(centerIndex, right)).toBe(true);

    // диагонали не считаются соседями
    const diag1 = getDistrictIndex(0, 0);
    const diag2 = getDistrictIndex(2, 0);
    const diag3 = getDistrictIndex(0, 2);
    const diag4 = getDistrictIndex(2, 2);

    expect(areDistrictsAdjacent(centerIndex, diag1)).toBe(false);
    expect(areDistrictsAdjacent(centerIndex, diag2)).toBe(false);
    expect(areDistrictsAdjacent(centerIndex, diag3)).toBe(false);
    expect(areDistrictsAdjacent(centerIndex, diag4)).toBe(false);
  });

  it('getAdjacentDistricts should return only valid neighbors inside grid', () => {
    // центр: 4 соседа
    const center = getDistrictIndex(1, 1);
    const centerNeighbors = getAdjacentDistricts(center).sort((a, b) => a - b);
    const expectedCenterNeighbors = [
      getDistrictIndex(1, 0), // up
      getDistrictIndex(1, 2), // down
      getDistrictIndex(0, 1), // left
      getDistrictIndex(2, 1), // right
    ].sort((a, b) => a - b);

    expect(centerNeighbors).toEqual(expectedCenterNeighbors);

    // угол: только 2 соседа
    const topLeft = getDistrictIndex(0, 0);
    const topLeftNeighbors = getAdjacentDistricts(topLeft).sort((a, b) => a - b);
    const expectedTopLeftNeighbors = [getDistrictIndex(1, 0), getDistrictIndex(0, 1)].sort(
      (a, b) => a - b,
    );

    expect(topLeftNeighbors).toEqual(expectedTopLeftNeighbors);
  });

  it('CENTRAL_DISTRICTS and CORNER_DISTRICTS should refer to valid cells', () => {
    CENTRAL_DISTRICTS.forEach((idx) => {
      expect(idx).toBeGreaterThanOrEqual(0);
      expect(idx).toBeLessThan(TOTAL_DISTRICTS);
    });

    CORNER_DISTRICTS.forEach((idx) => {
      expect(idx).toBeGreaterThanOrEqual(0);
      expect(idx).toBeLessThan(TOTAL_DISTRICTS);
    });
  });
});

import { describe, test, expect, beforeEach } from 'vitest';
import { 
  gameRules, 
  createGame, 
  frightenResidents, 
  killResident, 
  passKill,
  moveDetective,
  nextPhase 
} from './gameRules';
import type { NewGameConfig, GameState } from './gameTypes';
import { getDistrictForResident } from './gameConstants';

describe('City Mystery Game Rules', () => {
  let state: GameState;
  let config: NewGameConfig;

  beforeEach(() => {
    config = {
      mode: 'LOGIC',
      includeFigure: false,
      selectedMotives: ['MANIAC', 'SADIST', 'HEADHUNTER', 'VIGILANTE', 'KILLER', 'TERRORIST'],
    };
    state = createGame(config);
  });

  test('should create game with correct initial state', () => {
    expect(state.id).toBeDefined();
    expect(state.mode).toBe('LOGIC');
    expect(state.phase).toBe('KILLER');
    expect(state.step).toBe('FRIGHTEN');
    expect(state.round).toBe(1);
    expect(state.maxRounds).toBe(5);

    // Проверяем игровое поле
    expect(state.grid).toHaveLength(16); // 4x4 сетка

    // Считаем всех жителей
    const totalCitizens = state.grid.reduce((acc, cell) => acc + cell.length, 0);
    expect(totalCitizens).toBe(20);

    // Проверяем, что нет переполненных кварталов
    const overcrowded = state.grid.some((cell) => cell.length > 3);
    expect(overcrowded).toBe(false);

    // Проверяем убийцу
    expect(state.killer.identity).toBeDefined();
    expect(state.killer.motive).toBeDefined();
  });

  test('should allow killer to frighten residents', () => {
    // Находим двух жителей
    const residents = state.grid.flat();
    const detectivePos = state.detective.position;
    const availableResidents = residents.filter((resident) => {
      const district = getDistrictForResident(resident.id, state.grid);
      return district !== detectivePos;
    });

    const residentIds = [availableResidents[0].id, availableResidents[1].id];

    const result = frightenResidents(state, residentIds);

    expect(result.isValid).toBe(true);
    expect(result.state).toBeDefined();
    expect(result.state!.frightenedResidents).toContain(residentIds[0]);
    expect(result.state!.frightenedResidents).toContain(residentIds[1]);
    expect(result.state!.step).toBe('KILL');
  });

  test('should validate killer actions correctly', () => {
    // Переходим к фазе детектива
    const detectiveState = nextPhase(state).state!;

    // Попытка запугать в неправильной фазе
    const result = frightenResidents(detectiveState, ['test1', 'test2']);

    expect(result.isValid).toBe(false);
    expect(result.error).toContain('не этап запугивания');
  });

  test('should move to next phase correctly', () => {
    // Начальное состояние - фаза убийцы
    expect(state.phase).toBe('KILLER');

    // Переходим к детективу
    let result = nextPhase(state);
    expect(result.isValid).toBe(true);
    expect(result.state!.phase).toBe('DETECTIVE');

    // Переходим к фазе города
    result = nextPhase(result.state!);
    expect(result.isValid).toBe(true);
    expect(result.state!.phase).toBe('CITY');
    expect(result.state!.step).toBe('POPULATION');

    // Завершаем раунд
    result = nextPhase(result.state!);
    expect(result.isValid).toBe(true);
    expect(result.state!.phase).toBe('KILLER');
    expect(result.state!.round).toBe(2);
  });

  test('prevents killing resident in detective district', () => {
    // Переходим к этапу убийства
    state.step = 'KILL';

    const detectivePos = state.detective.position;
    const residentsInDetectiveDistrict = state.grid[detectivePos];

    if (residentsInDetectiveDistrict.length === 0) {
      // Пропускаем тест если нет жителей в квартале детектива
      return;
    }

    const victim = residentsInDetectiveDistrict[0];

    const result = killResident(state, victim.id, detectivePos);

    expect(result.isValid).toBe(false);
    expect(result.error).toContain('Нельзя убить в квартале с детективом');
  });

  test('prevents killer from committing suicide', () => {
    state.step = 'KILL';

    const killer = state.killer.identity;
    const killerDistrict = getDistrictForResident(killer.id, state.grid);

    // Убеждаемся что детектив НЕ в квартале убийцы
    if (killerDistrict === state.detective.position) {
      state.detective.position = (killerDistrict + 1) % 16;
    }

    expect(killerDistrict).not.toBeUndefined();

    const result = killResident(state, killer.id, killerDistrict as number);

    expect(result.isValid).toBe(false);
    expect(result.error).toContain('самоубийство');
  });

  test('allows killer to pass kill only once and extends max rounds', () => {
    state.step = 'KILL';

    const initialMaxRounds = state.maxRounds;

    const first = passKill(state);
    expect(first.isValid).toBe(true);
    expect(first.state!.maxRounds).toBe(initialMaxRounds + 1);

    // Вторая попытка с обновленным состоянием
    const secondState = { ...first.state!, step: 'KILL' as const };
    const second = passKill(secondState);

    expect(second.isValid).toBe(false);
    expect(second.error).toContain('только один раз');
  });

  test('detective wins when rounds exceed maxRounds after city phase', () => {
    state.phase = 'CITY';
    state.step = 'POPULATION';
    state.round = state.maxRounds;

    const result = nextPhase(state);
    expect(result.isValid).toBe(true);

    expect(result.state!.isGameOver).toBe(true);
    expect(result.state!.winner).toBe('DETECTIVE');
  });

  test('undo works via store history', () => {
    // Undo теперь реализован в store через history
    // Этот тест проверяет базовую иммутабельность

    const residents = state.grid.flat();
    const residentIds = [residents[0].id, residents[1].id];

    const originalStep = state.step;
    const result = frightenResidents(state, residentIds);

    // Оригинальный state не изменился
    expect(state.step).toBe(originalStep);
    expect(state.frightenedResidents).toEqual([]);

    // Новый state изменился
    expect(result.state!.step).toBe('KILL');
    expect(result.state!.frightenedResidents).toHaveLength(2);
  });
});

