  getDistrictForResident, areDistrictsAdjacent,
  MOTIVE_CARDS
} from './gameConstants';
import { interrogate, performTracking } from './engine';

// ==================== ТИПЫ ====================

export interface GameRuleResult {
  isValid: boolean;
  state?: GameState;
  error?: string;
  data?: Record<string, unknown>;
}

// ==================== УТИЛИТЫ ====================

/** Перемешать массив (иммутабельно) */
export function shuffle<T>(array: readonly T[]): T[] {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
}

/** Выбрать случайные элементы */
export function pickRandom<T>(array: readonly T[], count: number): T[] {
  return shuffle(array).slice(0, count);
}

/** Генератор ID */
export function generateId(prefix = ''): string {
  return `${prefix}${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/** Глубокое клонирование state */
function cloneState(state: GameState): GameState {
  return JSON.parse(JSON.stringify(state));
}

// ==================== ИНИЦИАЛИЗАЦИЯ ====================

/** Распределить жителей по кварталам */
function distributeCitizens(citizens: Citizen[]): Citizen[][] {
  const grid: Citizen[][] = Array.from({ length: 16 }, () => []);
  const shuffled = shuffle(citizens);

  shuffled.forEach((citizen, index) => {
    const districtIndex = index % 16;
    if (grid[districtIndex].length < 3) {
      grid[districtIndex].push(citizen);
    } else {
      // Найти квартал с местом
      for (let i = 0; i < 16; i++) {
        if (grid[i].length < 3) {
          grid[i].push(citizen);
          break;
        }
      }
    }
  });

  return grid;
}

/** Создать начальное состояние игры */
export function createGame(config: NewGameConfig = {
  mode: 'LOGIC',
  includeFigure: false,
  selectedMotives: BASE_MOTIVES
}): GameState {
  const selectedCitizens = pickRandom(allCitizens, 20);
  const killer = pickRandom(selectedCitizens, 1)[0];

  const figure = config.includeFigure
    ? pickRandom(selectedCitizens.filter(c => c.id !== killer.id), 1)[0]
    : null;

  const availableMotives = config.selectedMotives.length > 0
    ? config.selectedMotives
    : BASE_MOTIVES;
  const motive = pickRandom(availableMotives, 1)[0];

  const factions = [...new Set(allCitizens.map(c => c.faction))] as Faction[];
  const allies = pickRandom(factions, 1)[0];

  const grid = distributeCitizens(selectedCitizens);

  return {
    id: generateId('game-'),
    mode: config.mode,
    phase: 'KILLER',
    step: 'FRIGHTEN',
    round: 1,
    maxRounds: 5,
    grid,
    buildings: DEFAULT_BUILDINGS.map(b => ({ ...b, usedThisRound: false })),
    crimeScenes: [],
    frightenedResidents: [],
    detective: {
      position: 0,
      actionsLeft: 2,
      movementPoints: 2,
      trackingToken: { residentId: null, districtIndex: null },
    },
    killer: {
      identity: killer,
      motive,
      allies,
      figure,
    },
    victims: [],
    accusations: [],
    isGameOver: false,
    winner: null,
    history: [],
  };
}

// ==================== ДЕЙСТВИЯ УБИЙЦЫ ====================

/** Запугать жителей */
export function frightenResidents(
  state: GameState,
  residentIds: string[]
): GameRuleResult {
  // Валидация
  if (state.phase !== 'KILLER' || state.step !== 'FRIGHTEN') {
    return { isValid: false, error: 'Сейчас не этап запугивания' };
  }

  if (residentIds.length !== 2) {
    return { isValid: false, error: 'Нужно выбрать ровно 2 жителей' };
  }

  const allResidents = state.grid.flat();
  const validResidents = residentIds.every(id =>
    allResidents.some(r => r.id === id)
  );

  if (!validResidents) {
    return { isValid: false, error: 'Один или несколько жителей не найдены' };
  }

  // Клонируем и обновляем
  const newState = cloneState(state);
  newState.frightenedResidents = [...residentIds];
  newState.step = 'KILL';

  return { isValid: true, state: newState };
}

/** Проверка мотива для убийства */
function checkMotive(victim: Citizen, state: GameState): { isValid: boolean; error?: string } {
  const motiveCard = MOTIVE_CARDS.find(m => m.id === state.killer.motive);
  if (!motiveCard) {
    return { isValid: false, error: 'Мотив не найден' };
  }

  const condition = motiveCard.condition;
  const killer = state.killer.identity;

  switch (condition.type) {
    case 'SAME_PROPERTY':
      if (condition.property === 'faction') {
        return killer.faction === victim.faction
          ? { isValid: true }
          : { isValid: false, error: `Жертва должна быть из фракции ${killer.faction}` };
      }
      if (condition.property === 'gender') {
        return killer.gender === victim.gender
          ? { isValid: true }
          : { isValid: false, error: `Жертва должна быть пола ${killer.gender}` };
      }
      break;

    case 'DIFFERENT_PROPERTY':
      if (condition.property === 'faction') {
        return killer.faction !== victim.faction
          ? { isValid: true }
          : { isValid: false, error: 'Жертва должна быть из другой фракции' };
      }
      if (condition.property === 'gender') {
        return killer.gender !== victim.gender
          ? { isValid: true }
          : { isValid: false, error: 'Жертва должна быть другого пола' };
      }
      break;

    case 'HAS_PROPERTY':
      if (condition.property === 'isRich') {
        return victim.isRich
          ? { isValid: true }
          : { isValid: false, error: 'Жертва должна быть богатой' };
      }
      break;

    case 'LOCATION':
      // Проверка локации жертвы
      return { isValid: true };
  }

  return { isValid: true };
}

/** Убить жителя */
export function killResident(
  state: GameState,
  residentId: string,
  districtIndex: number
): GameRuleResult {
  if (state.step !== 'KILL') {
    return { isValid: false, error: 'Сейчас не этап убийства' };
  }

  const victim = state.grid.flat().find(c => c.id === residentId);
  if (!victim) {
    return { isValid: false, error: 'Жертва не найдена' };
  }

  const victimDistrict = getDistrictForResident(residentId, state.grid);

  // 1. Проверка самоубийства (первым!)
  if (residentId === state.killer.identity.id) {
    return { isValid: false, error: 'Убийца не может совершить самоубийство' };
  }

  // 2. Проверка детектива
  if (victimDistrict === state.detective.position) {
    return { isValid: false, error: 'Нельзя убить в квартале с детективом' };
  }

  // 3. Проверка больницы
  const hospitalInDistrict = state.buildings.find(
    b => b.type === 'HOSPITAL' && b.position === victimDistrict
  );
  if (hospitalInDistrict) {
    return { isValid: false, error: 'Нельзя убить в квартале с больницей' };
  }

  // 4. Проверка мотива
  const motiveCheck = checkMotive(victim, state);
  if (!motiveCheck.isValid) {
    return { isValid: false, error: `Не соответствует мотиву: ${motiveCheck.error}` };
  }

  // Клонируем и обновляем
  const newState = cloneState(state);

  // Убираем жертву
  const district = newState.grid[victimDistrict!];
  const victimIndex = district.findIndex(c => c.id === residentId);
  district.splice(victimIndex, 1);

  newState.victims.push(victim);
  newState.crimeScenes.push(victimDistrict!);

  if (newState.victims.length >= 5) {
    newState.isGameOver = true;
    newState.winner = 'KILLER';
  }

  newState.step = 'FRIGHTEN';

  return { isValid: true, state: newState };
}
/** Пропустить убийство */
export function passKill(state: GameState): GameRuleResult {
  if (state.step !== 'KILL') {
    return { isValid: false, error: 'Сейчас не этап убийства' };
  }

  if (state.maxRounds !== 5) {
    return { isValid: false, error: 'Убийство можно пропустить только один раз за игру' };
  }

  const newState = cloneState(state);
  newState.maxRounds = 6;
  newState.step = 'FRIGHTEN';

  return { isValid: true, state: newState };
}

// ==================== ДЕЙСТВИЯ ДЕТЕКТИВА ====================

/** Переместить детектива */
export function moveDetective(
  state: GameState,
  toDistrict: number
): GameRuleResult {
  if (state.phase !== 'DETECTIVE') {
    return { isValid: false, error: 'Сейчас не фаза детектива' };
  }

  if (state.detective.movementPoints < 1) {
    return { isValid: false, error: 'Нет очков движения' };
  }

  if (toDistrict < 0 || toDistrict > 15) {
    return { isValid: false, error: 'Неверный индекс квартала' };
  }

  if (state.crimeScenes.includes(toDistrict)) {
    return { isValid: false, error: 'Нельзя войти на место преступления' };
  }

  const newState = cloneState(state);
  newState.detective.position = toDistrict;
  newState.detective.movementPoints--;

  return { isValid: true, state: newState };
}

/** Допросить жителя */
export function interrogateResident(
  state: GameState,
  residentId: string,
  question: QuestionType,
  value: string
): GameRuleResult {
  if (state.detective.actionsLeft < 1) {
    return { isValid: false, error: 'Не осталось действий' };
  }

  const resident = state.grid.flat().find(c => c.id === residentId);
  if (!resident) {
    return { isValid: false, error: 'Житель не найден' };
  }

  const residentDistrict = getDistrictForResident(residentId, state.grid);
  if (residentDistrict !== state.detective.position) {
    return { isValid: false, error: 'Житель не в вашем квартале' };
  }

  if (state.frightenedResidents.includes(residentId)) {
    return { isValid: false, error: 'Житель запуган и не будет отвечать' };
  }

  // Проверка закусочной
  const dinerInDistrict = state.buildings.find(
    b => b.type === 'DINER' && b.position === state.detective.position
  );
  const forceTruth = !!dinerInDistrict;

  const result = interrogate(resident, question, value, state, forceTruth);

  const newState = cloneState(state);
  newState.detective.actionsLeft--;

  return { isValid: true, state: newState, data: result };
}

/** Использовать здание */
export function useBuilding(
  state: GameState,
  buildingType: BuildingType
): GameRuleResult {
  if (state.detective.actionsLeft < 1) {
    return { isValid: false, error: 'Не осталось действий' };
  }

  const building = state.buildings.find(
    b => b.type === buildingType && b.position === state.detective.position
  );

  if (!building) {
    return { isValid: false, error: 'В этом квартале нет такого здания' };
  }

  if (building.usedThisRound) {
    return { isValid: false, error: 'Это здание уже использовано в этом раунде' };
  }

  const newState = cloneState(state);
  const buildingInState = newState.buildings.find(
    b => b.type === buildingType && b.position === state.detective.position
  )!;

  buildingInState.usedThisRound = true;
  newState.detective.actionsLeft--;

  // Эффекты зданий
  switch (buildingType) {
    case 'POLICE':
      newState.detective.actionsLeft++;
      break;
    case 'FIRE_STATION':
      const adjacentScenes = state.crimeScenes.filter(scene =>
        scene === state.detective.position ||
        areDistrictsAdjacent(scene, state.detective.position)
      );
      if (adjacentScenes.length > 0) {
        newState.crimeScenes = newState.crimeScenes.filter(
          s => s !== adjacentScenes[0]
        );
      }
      break;
    // DINER и HOSPITAL — пассивные эффекты
  }

  return { isValid: true, state: newState };
}

/** Слежка за жителем */
export function trackResident(
  state: GameState,
  residentId: string
): GameRuleResult {
  const resident = state.grid.flat().find(c => c.id === residentId);
  if (!resident) {
    return { isValid: false, error: 'Житель не найден' };
  }

  if (state.detective.trackingToken.residentId !== residentId) {
    return { isValid: false, error: 'На этом жителе нет жетона слежки' };
  }

  const trackingResult = performTracking(residentId, state);

  const newState = cloneState(state);
  newState.detective.trackingToken = { residentId: null, districtIndex: null };

  return { isValid: true, state: newState, data: trackingResult };
}

// ==================== УПРАВЛЕНИЕ ФАЗАМИ ====================

/** Срочный вызов — переместить детектива на место преступления */
export function urgentCall(state: GameState): GameRuleResult {
  if (state.step !== 'URGENT_CALL') {
    return { isValid: false, error: 'Сейчас не срочный вызов' };
  }

  const latestCrimeScene = state.crimeScenes[state.crimeScenes.length - 1];
  if (latestCrimeScene === undefined) {
    return { isValid: false, error: 'Нет места преступления' };
  }

  const newState = cloneState(state);
  newState.detective.position = latestCrimeScene;
  newState.step = 'INVESTIGATE';
  newState.detective.actionsLeft = 2;
  newState.detective.movementPoints = 2;

  return { isValid: true, state: newState };
}

/** Перейти к следующей фазе */
export function nextPhase(state: GameState): GameRuleResult {
  const newState = cloneState(state);

  switch (state.phase) {
    case 'KILLER':
      newState.phase = 'DETECTIVE';
      newState.step = state.crimeScenes.length > 0 ? 'URGENT_CALL' : 'INVESTIGATE';
      newState.detective.actionsLeft = 2;
      newState.detective.movementPoints = 2;
      break;

    case 'DETECTIVE':
      newState.phase = 'CITY';
      newState.step = 'POPULATION';
      break;

    case 'CITY':
      // Сброс на новый раунд
      newState.phase = 'KILLER';
      newState.step = 'FRIGHTEN';
      newState.round++;
      newState.frightenedResidents = [];

      // Сброс зданий
      newState.buildings.forEach(b => { b.usedThisRound = false; });

      // Проверка победы детектива по раундам
      if (newState.round > newState.maxRounds) {
        newState.isGameOver = true;
        newState.winner = 'DETECTIVE';
      }
      break;
  }

  return { isValid: true, state: newState };
}

