/**
 * ActionPanel — панель действий игрока
 * Оркестрирует дочерние компоненты
 */

import React, { useState } from 'react';
import { useGameStore } from '../../application/gameStore';
import { PhaseInfo } from './PhaseInfo';
import { GameStats } from './GameStats';
import { KillerActions } from './KillerActions';
import { DetectiveActions } from './DetectiveActions';
import { InterrogationModal } from '../InterrogationModal';
import type { QuestionType } from '../../data/gameTypes';

export const ActionPanel: React.FC = () => {
  const {
    gameState,
    playerRole,
    selectedResidents,
    frightenResidents,
    killResident,
    passKill,
    interrogateResident,
    nextPhase,
    clearSelection,
  } = useGameStore();

  const [isInterrogationOpen, setIsInterrogationOpen] = useState(false);

  // Не инициализировано
  if (!gameState || !playerRole) {
    return (
      <div className="bg-gray-800/30 backdrop-blur-sm border border-gray-700 rounded-2xl p-6">
        <h3 className="text-xl font-bold mb-4 flex items-center">
          <span className="mr-3">🎮</span> Панель действий
        </h3>
        <div className="text-center text-gray-500 py-8">
          Игра не инициализирована. Выберите роль.
        </div>
      </div>
    );
  }

  const { phase, step, round, maxRounds, frightenedResidents, victims, detective } = gameState;
  const selectedCount = selectedResidents.length;

  // Получить выбранного жителя
  const getSelectedResident = () => {
    if (selectedCount !== 1) return null;
    return gameState.grid.flat().find(r => r.id === selectedResidents[0]) || null;
  };

  // === Обработчики убийцы ===
  const handleFrighten = () => {
    if (selectedCount === 2) {
      const result = frightenResidents(selectedResidents);
      if (result.isValid) {
        clearSelection();
      }
    }
  };

  const handleKill = () => {
    if (selectedCount === 1) {
      let districtIndex = -1;
      for (let i = 0; i < gameState.grid.length; i++) {
        if (gameState.grid[i].some(r => r.id === selectedResidents[0])) {
          districtIndex = i;
          break;
        }
      }
      if (districtIndex >= 0) {
        const result = killResident(selectedResidents[0], districtIndex);
        if (result.isValid) {
          clearSelection();
          nextPhase();
        }
      }
    }
  };

  const handlePassKill = () => {
    const result = passKill();
    if (result.isValid) {
      nextPhase();
    }
  };

  // === Обработчики детектива ===
  const handleOpenInterrogation = () => {
    if (selectedCount === 1) {
      setIsInterrogationOpen(true);
    }
  };

  const handleInterrogate = async (question: string, value: string) => {
    const result = interrogateResident(selectedResidents[0], question as QuestionType, value);
    if (result.isValid && result.data) {
      return {
        answer: result.data.answer,
        canLie: result.data.canLie,
      };
    }
    throw new Error(result.error || 'Ошибка допроса');
  };

  const handleCloseInterrogation = () => {
    setIsInterrogationOpen(false);
    clearSelection();
  };

  const handleTrack = () => {
    // TODO: выполнить слежку
    console.log('Слежка:', selectedResidents[0]);
  };

  const handleEndPhase = () => {
    nextPhase();
  };

  // === Определяем, чей ход ===
  const isKillerTurn = playerRole === 'KILLER' && phase === 'KILLER';
  const isDetectiveTurn = playerRole === 'DETECTIVE' && phase === 'DETECTIVE';
  const canPassKill = gameState.maxRounds === 5;
  const hasTrackingToken = detective.trackingToken.residentId !== null;
  const selectedResident = getSelectedResident();

  return (
    <div className="bg-gray-800/30 backdrop-blur-sm border border-gray-700 rounded-2xl p-6">
      <h3 className="text-xl font-bold mb-4 flex items-center">
        <span className="mr-3">🎮</span> Панель действий
      </h3>

      {/* Информация о фазе */}
      <PhaseInfo phase={phase} step={step} playerRole={playerRole} />

      {/* Кнопки действий */}
      <div className="my-6">
        {isKillerTurn && (
          <KillerActions
            step={step}
            selectedCount={selectedCount}
            canKill={selectedCount === 1}
            canPassKill={canPassKill}
            onFrighten={handleFrighten}
            onKill={handleKill}
            onPassKill={handlePassKill}
          />
        )}

        {isDetectiveTurn && (
          <DetectiveActions
            step={step}
            actionsLeft={detective.actionsLeft}
            movementPoints={detective.movementPoints}
            selectedCount={selectedCount}
            hasTrackingToken={hasTrackingToken}
            onInterrogate={handleOpenInterrogation}
            onTrack={handleTrack}
            onEndPhase={handleEndPhase}
          />
        )}

        {!isKillerTurn && !isDetectiveTurn && (
          <div className="text-center text-gray-500 py-4">
            Ожидайте своего хода...
          </div>
        )}
      </div>

      {/* Статистика */}
      <div className="pt-4 border-t border-gray-700">
        <GameStats
          round={round}
          maxRounds={maxRounds}
          victimsCount={victims.length}
          frightenedCount={frightenedResidents.length}
          selectedCount={selectedCount}
        />
      </div>

      {/* Модалка допроса */}
      <InterrogationModal
        residentName={selectedResident?.role || 'Житель'}
        residentId={selectedResidents[0] || ''}
        isOpen={isInterrogationOpen}
        onClose={handleCloseInterrogation}
        onInterrogate={handleInterrogate}
      />
    </div>
  );
};

import React from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { FACTION_ICONS } from '../data/gameConstants';

interface CitizenCardProps {
  citizen: {
    id: string;
    role: string;
    gender: 'MALE' | 'FEMALE';
    age: number;
    build: string;
    faction: string;
  };
  isFrightened: boolean;
  isSelected: boolean;
  onClick: () => void;
}

/**
 * Анимированная карточка жителя
 * - Плавное выделение при выборе
 * - Пружинистая анимация нажатия
 * - Свечение для выбранных
 */
export const CitizenCard: React.FC<CitizenCardProps> = ({
  citizen,
  isFrightened,
  isSelected,
  onClick,
}) => {
  const genderSymbol = citizen.gender === 'MALE' ? '♂' : '♀';

  // Базовые стили
  const baseClasses = [
    'w-full',
    'flex',
    'flex-col',
    'gap-0.5',
    'rounded-lg',
    'border',
    'px-1.5',
    'py-1',
    'text-[10px]',
    'leading-tight',
    'bg-gray-900/70',
    'relative',
    'overflow-hidden',
  ];

  // Условные стили
  if (isFrightened) {
    baseClasses.push('border-gray-600', 'bg-gray-800/80', 'opacity-60');
  } else if (isSelected) {
    baseClasses.push('border-yellow-400', 'bg-yellow-900/30');
  } else {
    baseClasses.push('border-gray-700', 'hover:border-gray-500', 'cursor-pointer');
  }

  return (
    <motion.button
      type="button"
      className={baseClasses.join(' ')}
      onClick={onClick}
      disabled={isFrightened}
      // Анимация нажатия
      whileTap={{ scale: 0.95 }}
      whileHover={!isFrightened ? { scale: 1.02 } : undefined}
      // Плавный переход состояний
      animate={{
        borderColor: isSelected ? '#facc15' : '#374151',
        backgroundColor: isSelected 
          ? 'rgba(113, 63, 18, 0.3)' 
          : 'rgba(17, 24, 39, 0.7)',
      }}
      transition={{ duration: 0.2 }}
    >
      {/* Свечение при выборе */}
      <AnimatePresence>
        {isSelected && (
          <motion.div
            className="absolute inset-0 rounded-lg"
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: 1,
              boxShadow: '0 0 15px rgba(250, 204, 21, 0.4), inset 0 0 10px rgba(250, 204, 21, 0.1)'
            }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.2 }}
          />
        )}
      </AnimatePresence>

      {/* Иконка запугивания */}
      <AnimatePresence>
        {isFrightened && (
          <motion.div
            className="absolute top-0 right-0 text-xs"
            initial={{ scale: 0, rotate: -180 }}
            animate={{ scale: 1, rotate: 0 }}
            exit={{ scale: 0 }}
            transition={{ type: 'spring', stiffness: 500, damping: 25 }}
          >
            😨
          </motion.div>
        )}
      </AnimatePresence>

      {/* Контент */}
      <div className="relative z-10">
        {/* Первая строка: роль + пол/возраст */}
        <div className="flex items-center justify-between gap-1">
          <span className="truncate font-semibold max-w-[65%]">
            {citizen.role}
          </span>
          <span className="text-[9px] text-gray-400 font-mono whitespace-nowrap">
            {genderSymbol}{citizen.age}
          </span>
        </div>

        {/* Вторая строка: телосложение + фракция */}
        <div className="flex items-center justify-between gap-1 text-[9px] text-gray-300">
          <span className="truncate max-w-[70%]">
            {citizen.build}
          </span>
          <span className="inline-flex items-center justify-center px-1 py-[1px] rounded bg-gray-800/80">
            <span className="text-xs leading-none">
              {FACTION_ICONS[citizen.faction]}
            </span>
          </span>
        </div>
      </div>
    </motion.button>
  );
};

import React from 'react';
import { Citizen } from '../data/citizens';

interface CityGridProps {
  grid: Citizen[][]; // 16 клеток
  detectivePos: number; // Где стоит детектив (0-15)
}

export const CityGrid: React.FC<CityGridProps> = ({ grid, detectivePos }) => {
  return (
    <div className="grid grid-cols-4 gap-2 p-4 bg-gray-900 rounded-lg max-w-md mx-auto aspect-square">
      {grid.map((citizens, cellIndex) => {
        const isDetectiveHere = cellIndex === detectivePos;

        return (
          <div 
            key={cellIndex}
            className={`
              relative border-2 rounded p-1 flex flex-col items-center justify-center text-xs
              ${isDetectiveHere ? 'border-blue-500 bg-blue-900/30' : 'border-gray-700 bg-gray-800'}
              hover:border-yellow-500 cursor-pointer transition-colors
            `}
            style={{ minHeight: '80px' }}
          >
            {/* Номер квартала (для отладки) */}
            <span className="absolute top-0 left-1 text-[10px] text-gray-600 font-mono">
              {cellIndex}
            </span>

            {/* Фишка Детектива */}
            {isDetectiveHere && (
              <div className="absolute -top-2 -right-2 text-2xl z-10 animate-bounce">
                🕵️‍♂️
              </div>
            )}

            {/* Жители в квартале */}
            <div className="flex flex-wrap justify-center gap-1 mt-2">
              {citizens.map((citizen) => (
                <div 
                  key={citizen.id}
                  className="bg-gray-700 text-gray-200 px-1 rounded shadow-sm border border-gray-600 text-[10px] truncate w-full text-center"
                  title={`${citizen.role} (${citizen.faction})`}
                >
                  {citizen.role}
                </div>
              ))}

              {/* Если пусто */}
              {citizens.length === 0 && !isDetectiveHere && (
                <span className="text-gray-600">-</span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

