import React, { useEffect, useState } from 'react';
import { useGameStore } from '../application/gameStore';
import { useTelegramUser } from '../../../application/useTelegram';
import { GameBoard } from './GameBoard';
import { ActionPanel } from './ActionPanel';
import { MotiveGrid } from './MotiveGrid';
import { GameLog } from './GameLog';
import { LobbyScreen } from './LobbyScreen';
import { GameOverScreen } from './GameOverScreen';
import { BUILDING_ICONS, FACTION_ICONS } from '../data/gameConstants';

// Вспомогательная функция для координат квартала
function getCoordinatesFromIndex(index: number): { x: number; y: number } {
  return {
    x: index % 4,
    y: Math.floor(index / 4),
  };
}

export const CityMysteryPage: React.FC = () => {
  const telegramUser = useTelegramUser();
  const [showTutorial, setShowTutorial] = useState(false);
  const [focusedDistrict, setFocusedDistrict] = useState<number | null>(null);

  // Получаем состояние из store
  const {
    gameState,
    playerRole,
    isGameInitialized,
    initializeGame,
    setPlayerRole,
    error,
    clearError,
  } = useGameStore();

  // Инициализируем игру при монтировании
  useEffect(() => {
    if (!isGameInitialized) {
      initializeGame({
        mode: 'LOGIC',
        includeFigure: false,
        selectedMotives: [], // Используем мотивы по умолчанию
      });
    }
  }, [initializeGame, isGameInitialized]);

  // Показываем лобби, если игра не инициализирована или роль не выбрана
  if (!isGameInitialized || !playerRole) {
    return (
      <LobbyScreen
        onSelectRole={setPlayerRole}
        onStartTutorial={() => setShowTutorial(true)}
        userName={telegramUser?.firstName}
      />
    );
  }

  // Показываем экран конца игры
  if (gameState?.isGameOver) {
    return (
      <GameOverScreen
        winner={gameState.winner!}
        reason={gameState.reason}
        victims={gameState.victims}
        onRestart={() =>
          initializeGame({ mode: 'LOGIC', includeFigure: false, selectedMotives: [] })
        }
      />
    );
  }

  // Основной игровой интерфейс
  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-900 to-black text-white p-4">
      <div className="max-w-7xl mx-auto">
        {/* Шапка игры */}
        <header className="mb-6">
          <div className="flex justify-between items-center mb-4">
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-red-600 to-blue-600 bg-clip-text text-transparent">
                ГОРОДСКОЙ УБИЙЦА
              </h1>
              <p className="text-gray-400 text-sm mt-1">Детективная игра в стиле нуар</p>
            </div>

            <div className="flex items-center space-x-4">
              {telegramUser && (
                <div className="text-right">
                  <p className="text-sm text-gray-400">Игрок</p>
                  <p className="font-bold">{telegramUser.firstName}</p>
                </div>
              )}

              <button
                onClick={() => setShowTutorial(!showTutorial)}
                className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-lg"
              >
                {showTutorial ? '✕ Скрыть помощь' : '❓ Помощь'}
              </button>
            </div>
          </div>

          {/* Панель статуса игры */}
          {gameState && (
            <div className="bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-xl p-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="text-center">
                  <div className="text-sm text-gray-400">Раунд</div>
                  <div className="text-2xl font-bold">
                    {gameState.round}
                    <span className="text-gray-500">/{gameState.maxRounds}</span>
                  </div>
                </div>

                <div className="text-center">
                  <div className="text-sm text-gray-400">Фаза</div>
                  <div className="text-xl font-bold flex items-center justify-center">
                    {gameState.phase === 'KILLER' && <span className="mr-2">🔪</span>}
                    {gameState.phase === 'DETECTIVE' && <span className="mr-2">🕵️</span>}
                    {gameState.phase === 'CITY' && <span className="mr-2">🏙️</span>}
                    {gameState.phase === 'KILLER'
                      ? 'Убийца'
                      : gameState.phase === 'DETECTIVE'
                        ? 'Детектив'
                        : 'Город'}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-sm text-gray-400">Ваша роль</div>
                  <button
                    onClick={() => setPlayerRole(playerRole === "KILLER" ? "DETECTIVE" : "KILLER")}
                    className="text-xl font-bold hover:opacity-80 transition-opacity cursor-pointer"
                    title="Клик для смены роли (тест)"
                  >
                    {playerRole === "KILLER" ? "🔪 Убийца" : "🕵️ Детектив"}
                    <span className="text-xs text-gray-500 ml-2">↔</span>
                  </button>
                </div>
                <div className="text-center">
                  <div className="text-sm text-gray-400">Жертвы</div>
                  <div className="text-2xl font-bold text-red-400">
                    {gameState.victims.length}
                    <span className="text-gray-500">/5</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </header>

        {/* Сообщение об ошибке */}
        {error && (
          <div className="mb-6 p-4 bg-red-900/50 border border-red-700 rounded-lg">
            <div className="flex justify-between items-center">
              <span className="text-red-200">⚠️ {error}</span>
              <button onClick={clearError} className="text-red-300 hover:text-white">
                ✕
              </button>
            </div>
          </div>
        )}

        {/* Туториал/помощь */}
        {showTutorial && (
          <div className="mb-6 p-6 bg-gray-800/80 backdrop-blur-sm border border-blue-500/50 rounded-xl">
            <h3 className="text-xl font-bold mb-4 text-blue-300">📚 Как играть</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <h4 className="font-bold mb-2 text-red-300">🔪 За Убийцу:</h4>
                <ul className="space-y-2 text-sm">
                  <li>• Каждый раунд запугивайте 2 жителей</li>
                  <li>• Убивайте жителей, следуя своему мотиву</li>
                  <li>• Избегайте кварталов с детективом</li>
                  <li>• Скрывайте свою личность и мотив</li>
                </ul>
              </div>
              <div>
                <h4 className="font-bold mb-2 text-blue-300">🕵️ За Детектива:</h4>
                <ul className="space-y-2 text-sm">
                  <li>• Допрашивайте жителей, задавая вопросы</li>
                  <li>• Используйте здания для особых действий</li>
                  <li>• Следите за подозрительными жителями</li>
                  <li>• Вычислите мотив и личность убийцы</li>
                </ul>
              </div>
            </div>
            <div className="mt-4 pt-4 border-t border-gray-700">
              <h4 className="font-bold mb-2">🎯 Цель игры:</h4>
              <p className="text-sm">
                <span className="text-red-400">Убийца:</span> Совершить 5 убийств, следуя мотиву
                <br />
                <span className="text-blue-400">Детектив:</span> Найти убийцу и его мотив до 5-го
                убийства
              </p>
            </div>
          </div>
        )}

        {/* Основное игровое поле */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Левая колонка: Игровое поле и действия */}
          <div className="lg:col-span-2 space-y-6">
            <GameBoard onDistrictClick={setFocusedDistrict} />
            <ActionPanel />
          </div>

          {/* Правая колонка: Информация */}
          <div className="space-y-6">
            <MotiveGrid />

            {/* Список жертв */}
            {gameState && gameState.victims.length > 0 && (
              <div className="bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-xl p-4">
                <h3 className="font-bold mb-3 text-red-400 flex items-center">
                  <span className="mr-2">💀</span> Жертвы ({gameState.victims.length}/5)
                </h3>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                  {gameState.victims.map((victim, index) => (
                    <div
                      key={victim.id}
                      className="flex items-center justify-between p-3 bg-gray-900/50 rounded-lg hover:bg-gray-800/50 transition-colors"
                    >
                      <div className="flex items-center">
                        <span className="text-gray-400 mr-3 text-sm">{index + 1}.</span>
                        <div>
                          <div className="font-medium">{victim.role}</div>
                          <div className="flex items-center mt-1">
                            <span className="text-xs bg-gray-700 px-2 py-1 rounded mr-2">
                              {FACTION_ICONS[victim.faction]} {victim.faction}
                            </span>
                            <span className="text-xs text-gray-400">
