                          <div
                            key={resident.id}
                            className="p-3 rounded-lg bg-gray-800/70 border border-gray-700 flex justify-between items-center"
                          >
                            <div>
                              <div className="font-medium">{resident.role}</div>
                              <div className="flex items-center mt-1 text-xs text-gray-400 space-x-2">
