/**
 * Анимированное игровое поле 4x4
 * - Плавное перемещение детектива (layoutId)
 * - Анимация мест преступления
 * - Подсветка доступных кварталов
 */

import React from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { useGameStore } from '../application/gameStore';
import { CitizenCard } from './CitizenCard';
import { BUILDING_ICONS } from '../data/gameConstants';

const MAX_SLOTS_PER_DISTRICT = 3;

const DISTRICT_NAMES: string[] = [
  'Старый порт', 'Набережная', 'Деловой центр', 'Северные доки',
  'Рынок', 'Старый город', 'Квартал баров', 'Администрация',
  'Парк', 'Жилые кварталы', 'Индустриальная зона', 'Пригород',
  'Вокзал', 'Больничный городок', 'Университет', 'Складской район',
];

function getCoordinates(index: number): { x: number; y: number } {
  return { x: index % 4, y: Math.floor(index / 4) };
}

export const GameBoard: React.FC = () => {
  const {
    gameState,
    playerRole,
    selectResident,
    selectedResidents,
    moveDetective,
  } = useGameStore();

  if (!gameState) return null;

  const canMoveToDistrict = (index: number): boolean => {
    return (
      playerRole === 'DETECTIVE' &&
      gameState.phase === 'DETECTIVE' &&
      gameState.step === 'INVESTIGATE' &&
      gameState.detective.movementPoints > 0 &&
      index !== gameState.detective.position &&
      !gameState.crimeScenes.includes(index)
    );
  };

  const handleDistrictClick = (index: number) => {
    if (canMoveToDistrict(index)) {
      moveDetective(index);
    }
  };

  return (
    <motion.div 
      className="bg-gray-800/30 backdrop-blur-sm border border-gray-700 rounded-2xl p-6"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
    >
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold flex items-center">
          <span className="mr-3">🗺️</span> Город (4×4 квартала)
        </h3>
        <div className="text-sm text-gray-400">
          {gameState.grid.flat().length} жителей • {gameState.buildings.length} зданий
        </div>
      </div>

      <div className="grid grid-cols-4 gap-3">
        {gameState.grid.map((district, index) => {
          const { x, y } = getCoordinates(index);
          const building = gameState.buildings.find((b) => b.position === index);
          const title = DISTRICT_NAMES[index] ?? `Квартал ${index + 1}`;

          const isCrimeScene = gameState.crimeScenes.includes(index);
          const isDetectiveHere = gameState.detective.position === index;
          const canMove = canMoveToDistrict(index);

          return (
            <motion.div
              key={index}
              className={`
                relative border-2 rounded-2xl p-3 aspect-square overflow-hidden
                transition-colors duration-200
                ${isCrimeScene ? 'bg-red-900/20 border-red-700/70' : 'bg-gray-900/40 border-gray-700'}
                ${isDetectiveHere ? 'ring-2 ring-blue-500 ring-opacity-60' : ''}
                ${canMove ? 'cursor-pointer hover:border-blue-400 hover:bg-blue-900/20' : ''}
              `}
              onClick={() => handleDistrictClick(index)}
              whileHover={canMove ? { scale: 1.02 } : undefined}
              whileTap={canMove ? { scale: 0.98 } : undefined}
            >
              {/* Координаты */}
              <div className="absolute top-2 right-2 text-[10px] text-gray-500 font-mono">
                [{y},{x}]
              </div>

              {/* Иконка здания */}
              {building && (
                <motion.div 
                  className="absolute top-2 left-2 text-2xl"
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ type: 'spring', stiffness: 500, damping: 25 }}
                >
                  {BUILDING_ICONS[building.type]}
                </motion.div>
              )}

              {/* Место преступления */}
              <AnimatePresence>
                {isCrimeScene && (
                  <motion.div
                    className="pointer-events-none absolute inset-0 flex items-center justify-center text-5xl"
                    initial={{ scale: 0, opacity: 0 }}
                    animate={{ scale: 1, opacity: 0.15 }}
                    exit={{ scale: 0, opacity: 0 }}
                    transition={{ type: 'spring', stiffness: 300 }}
                  >
                    💀
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Детектив (с layoutId для плавного перемещения) */}
              <AnimatePresence>
                {isDetectiveHere && (
                  <motion.div
                    layoutId="detective"
                    className="absolute bottom-2 right-2 text-2xl drop-shadow-lg"
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    transition={{ type: 'spring', stiffness: 400, damping: 25 }}
                  >
                    🕵️
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Индикатор доступности перемещения */}
              {canMove && (
                <motion.div
                  className="absolute inset-0 rounded-2xl border-2 border-blue-400/50"
                  animate={{ opacity: [0.3, 0.6, 0.3] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
              )}

              {/* Контент квартала */}
              <div className="relative z-10 flex h-full flex-col pt-6">
                <div className="mb-2 text-center text-[13px] font-semibold text-gray-100 truncate">
                  {title}
                </div>

                <div className="flex flex-1 flex-col gap-2">
                  {Array.from({ length: MAX_SLOTS_PER_DISTRICT }).map((_, slotIndex) => {
                    const citizen = district[slotIndex];

                    return (
                      <div
                        key={slotIndex}
                        className="flex-1 rounded-xl border border-gray-700/70 bg-gray-900/60 px-2 py-1.5 flex items-stretch overflow-hidden"
                      >
                        {citizen ? (
                          <div className="flex-1">
                            <CitizenCard
                              citizen={citizen}
                              isFrightened={gameState.frightenedResidents.includes(citizen.id)}
                              isSelected={selectedResidents.includes(citizen.id)}
                              onClick={() => selectResident(citizen.id)}
                            />
                          </div>
                        ) : (
                          <div className="flex flex-1 items-center justify-center text-[11px] text-gray-600">
                            {district.length === 0 && slotIndex === 1 ? 'Пусто' : null}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>
    </motion.div>
  );
};

